<?php

function supported_languages(): array {
    return [
        'en' => ['name' => 'English', 'native' => 'English', 'dir' => 'ltr'],
        'fr' => ['name' => 'French', 'native' => 'Français', 'dir' => 'ltr'],
        'ar' => ['name' => 'Arabic', 'native' => 'العربية', 'dir' => 'rtl'],
        'pt' => ['name' => 'Portuguese', 'native' => 'Português', 'dir' => 'ltr'],
        'sw' => ['name' => 'Swahili', 'native' => 'Kiswahili', 'dir' => 'ltr'],
    ];
}

function current_language(): string {
    static $language;
    if ($language !== null) {
        return $language;
    }
    $supported = supported_languages();
    $requested = strtolower(trim((string)($_GET['lang'] ?? '')));
    if ($requested !== '' && isset($supported[$requested])) {
        $_SESSION['language'] = $requested;
        setcookie('adr_language', $requested, [
            'expires' => time() + 31536000,
            'path' => '/',
            'secure' => !empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off',
            'httponly' => false,
            'samesite' => 'Lax',
        ]);
    }
    $saved = strtolower((string)($_SESSION['language'] ?? $_COOKIE['adr_language'] ?? 'en'));
    $language = isset($supported[$saved]) ? $saved : 'en';
    return $language;
}

function language_direction(): string {
    return supported_languages()[current_language()]['dir'] ?? 'ltr';
}

function language_name(string $code): string {
    return supported_languages()[$code]['native'] ?? strtoupper($code);
}

