function localized_region(string $region): string {
    $key = 'region_' . str_replace(' ', '_', strtolower($region));
    return t($key);
}

function entity_type_label(string $type): string {
    return t('entity_' . $type);
}

function membership_role_label(string $role): string {
    return t('role_' . $role);
}

function t(string $key, array $replace = []): string {
    $language = current_language();
    $sets = translations();
    $extended = extended_translations();
    $value = $sets[$language][$key] ?? $extended[$language][$key] ?? $sets['en'][$key] ?? $extended['en'][$key] ?? $key;
    foreach ($replace as $name => $replacement) {
        $value = str_replace('{' . $name . '}', (string)$replacement, $value);
    }
    return $value;
}

function language_switcher_fields(): string {
    $html = '';
    foreach ($_GET as $key => $value) {
        if ($key === 'lang' || is_array($value)) {
            continue;
        }
        $html .= '<input type="hidden" name="' . e($key) . '" value="' . e((string)$value) . '">';
    }
    return $html;
}
